export function QuoteRequestForm({
  heading = "{{heading}}",
  submitLabel = "{{submitLabel}}",
  layout = "{{layout}}",
  showBudgetField = {{showBudgetField}},
  accent = "{{accent}}",
}) {
  const fieldStyle = {
    display: "flex",
    flexDirection: layout === "inline" ? "row" : "column",
    alignItems: layout === "inline" ? "center" : "stretch",
    justifyContent: layout === "inline" ? "space-between" : "flex-start",
    gap: layout === "inline" ? 12 : 6,
  };
  const inputStyle = { font: "inherit", padding: "8px 10px", borderRadius: 8, border: "1.5px solid #24143030", background: "#fff", color: "#241430" };
  return (
    <form aria-label={heading} style={{ display: "grid", gap: 16, maxWidth: 380, padding: 24, borderRadius: 14, background: "#FAF7F2", color: "#241430", fontFamily: "system-ui, sans-serif" }}>
      <h3 style={{ margin: 0, fontSize: 18, fontWeight: 600 }}>{heading}</h3>
      <div style={fieldStyle}>
        <label htmlFor="qrf-r-name" style={{ fontSize: 13, fontWeight: 600 }}>Name</label>
        <input id="qrf-r-name" name="name" type="text" required style={inputStyle} />
      </div>
      <div style={fieldStyle}>
        <label htmlFor="qrf-r-email" style={{ fontSize: 13, fontWeight: 600 }}>Email</label>
        <input id="qrf-r-email" name="email" type="email" required style={inputStyle} />
      </div>
      {showBudgetField && (
        <div style={fieldStyle}>
          <label htmlFor="qrf-r-budget" style={{ fontSize: 13, fontWeight: 600 }}>Estimated budget</label>
          <select id="qrf-r-budget" name="budget" style={inputStyle}>
            <option>Under $1,000</option>
            <option>$1,000 - $5,000</option>
            <option>$5,000+</option>
          </select>
        </div>
      )}
      <div style={fieldStyle}>
        <label htmlFor="qrf-r-details" style={{ fontSize: 13, fontWeight: 600 }}>Project details</label>
        <textarea id="qrf-r-details" name="details" rows={4} required style={inputStyle} />
      </div>
      <button type="submit" style={{ padding: 12, borderRadius: 8, border: "none", background: accent, color: "#241430", fontSize: 15, fontWeight: 600, cursor: "pointer" }}>
        {submitLabel}
      </button>
    </form>
  );
}
